{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-bAm3M7/src/parse.js","content":"import { Fail } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

/**
 * Parses the build-graph text format described in the task: `task <name>
 * <cost>` declarations and `dep <name> <dependency>...` edges, one per
 * line, with blank lines and `#` comments ignored.
 *
 * Returns `{ taskNames, cost, deps }` where `taskNames` is every declared
 * task name in ascending order, `cost` maps a name to its declared cost,
 * and `deps` maps a name to the `Set` of names it depends on (only present
 * for names that appear as the first name of a `dep` line).
 *
 * Throws a `Fail` with exit code 2 for any malformed line or dependency on
 * an undeclared task.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const deps = new Map()
  const depUses = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new Fail(2, `line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_PATTERN.test(name)) {
        throw new Fail(2, `line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_PATTERN.test(costText)) {
        throw new Fail(2, `line ${lineNo}: cost must be a non-negative integer`)
      }
      if (cost.has(name)) {
        throw new Fail(2, `line ${lineNo}: task ${name} is declared twice`)
      }
      cost.set(name, parseInt(costText, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new Fail(2, `line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, name, ...dependencies] = words
      depUses.push(name, ...dependencies)
      let set = deps.get(name)
      if (!set) {
        set = new Set()
        deps.set(name, set)
      }
      for (const dependency of dependencies) set.add(dependency)
    } else {
      throw new Fail(2, `line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of depUses) {
    if (!cost.has(name)) {
      throw new Fail(2, `unknown task ${name}`)
    }
  }

  const taskNames = [...cost.keys()].sort()
  return { taskNames, cost, deps }
}
"}

