{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-bAm3M7/src/cycle.js","content":"/**
 * Finds the first cycle a depth-first search discovers when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the cycle as an array of names, from the
 * re-entered task through the search stack back to a repeat of itself, or
 * `null` when the graph is acyclic.
 */
export function findCycle(taskNames, deps) {
  const state = new Map()

  for (const start of taskNames) {
    if (state.get(start) === 'done') continue

    const stack = [{ name: start, rest: sortedDeps(start) }]
    state.set(start, 'visiting')

    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      if (frame.rest.length === 0) {
        state.set(frame.name, 'done')
        stack.pop()
        continue
      }
      const next = frame.rest.shift()
      const nextState = state.get(next)
      if (nextState === 'visiting') {
        const names = stack.map((f) => f.name)
        return names.slice(names.indexOf(next)).concat(next)
      }
      if (nextState !== 'done') {
        state.set(next, 'visiting')
        stack.push({ name: next, rest: sortedDeps(next) })
      }
    }
  }

  return null

  function sortedDeps(name) {
    return [...(deps.get(name) || [])].sort()
  }
}
"}

