{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-bAm3M7/src/schedule.js","content":"/**
 * Computes a value for every task in `taskNames` by combining the already
 * computed values of its dependencies, visiting dependencies before the
 * tasks that use them. `combine(name, depSet, results)` returns the value
 * for `name` given the `Set` of names it depends on and a `Map` of results
 * already computed for those dependencies. Iterative, so it is safe on
 * long dependency chains.
 */
function computeOnDag(taskNames, deps, combine) {
  const result = new Map()

  for (const start of taskNames) {
    if (result.has(start)) continue

    const stack = [{ name: start, expanded: false }]
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      if (result.has(frame.name)) {
        stack.pop()
        continue
      }
      if (!frame.expanded) {
        frame.expanded = true
        for (const dep of deps.get(frame.name) || []) {
          if (!result.has(dep)) stack.push({ name: dep, expanded: false })
        }
      } else {
        const depSet = deps.get(frame.name) || new Set()
        result.set(frame.name, combine(frame.name, depSet, result))
        stack.pop()
      }
    }
  }

  return result
}

/**
 * The wave a task sits in: 0 when it has no dependency, otherwise one more
 * than the deepest wave among its dependencies.
 */
export function computeDepths(taskNames, deps) {
  return computeOnDag(taskNames, deps, (name, depSet, result) => {
    let depth = 0
    for (const dep of depSet) depth = Math.max(depth, result.get(dep) + 1)
    return depth
  })
}

/**
 * Each task's `{ start, finish }` with unlimited workers: start is the
 * greatest finish among its dependencies (0 when it has none), and finish
 * is start plus its own cost.
 */
export function computeTiming(taskNames, deps, cost) {
  return computeOnDag(taskNames, deps, (name, depSet, result) => {
    let start = 0
    for (const dep of depSet) start = Math.max(start, result.get(dep).finish)
    return { start, finish: start + cost.get(name) }
  })
}

/**
 * A task's priority for `pack`: the cost of the longest chain that begins
 * at it, its own cost plus the greatest priority among its dependencies
 * (0 when it has none).
 */
export function computePriority(taskNames, deps, cost) {
  return computeOnDag(taskNames, deps, (name, depSet, result) => {
    let best = 0
    for (const dep of depSet) best = Math.max(best, result.get(dep))
    return cost.get(name) + best
  })
}

/**
 * Simulates the graph on `workerCount` workers as described in the task:
 * at each instant, while a worker is free and some task is ready, the
 * ready task with the greatest priority (ties broken by ascending name)
 * starts on the free worker with the smallest index; time then advances
 * to the next instant a worker frees up. Returns `{ logs, makespan }`
 * where `logs[i]` is the ordered list of `{ name, start, finish }` worker
 * `i` ran.
 */
export function packWorkers(taskNames, deps, cost, priority, workerCount) {
  const remaining = new Set(taskNames)
  const finishTime = new Map()
  const workerBusyUntil = new Array(workerCount).fill(0)
  const logs = Array.from({ length: workerCount }, () => [])
  let time = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerBusyUntil[i] <= time) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      let best = null
      for (const name of remaining) {
        if (!isReady(name, time, deps, finishTime)) continue
        if (best === null) {
          best = name
          continue
        }
        const p = priority.get(name)
        const bp = priority.get(best)
        if (p > bp || (p === bp && name < best)) best = name
      }
      if (best === null) break

      const worker = freeWorkers[0]
      const start = time
      const finish = start + cost.get(best)
      logs[worker].push({ name: best, start, finish })
      workerBusyUntil[worker] = finish
      finishTime.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let nextTime = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerBusyUntil[i] > time) nextTime = Math.min(nextTime, workerBusyUntil[i])
    }
    if (nextTime === Infinity) break
    time = nextTime
  }

  let makespan = 0
  for (const finish of finishTime.values()) makespan = Math.max(makespan, finish)
  return { logs, makespan }
}

function isReady(name, time, deps, finishTime) {
  for (const dep of deps.get(name) || []) {
    const finish = finishTime.get(dep)
    if (finish === undefined || finish > time) return false
  }
  return true
}
"}

