 * Each task's `{ start, finish }` with unlimited workers: start is the
 * greatest finish among its dependencies (0 when it has none), and finish
 * is start plus its own cost.
 */
export function computeTiming(taskNames, deps, cost) {
  return computeOnDag(taskNames, deps, (name, depSet, result) => {
    let start = 0
    for (const dep of depSet) start = Math.max(start, result.get(dep).finish)
    return { start, finish: start + cost.get(name) }
  })
