/**
 * A task's priority for `pack`: the cost of the longest chain that begins
 * at it, its own cost plus the greatest priority among its dependencies
 * (0 when it has none).
 */
export function computePriority(taskNames, deps, cost) {
  return computeOnDag(taskNames, deps, (name, depSet, result) => {
    let best = 0
    for (const dep of depSet) best = Math.max(best, result.get(dep))
    return cost.get(name) + best
  })
