      const worker = freeWorkers[0]
      const start = time
      const finish = start + cost.get(best)
      logs[worker].push({ name: best, start, finish })
      workerBusyUntil[worker] = finish
      finishTime.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

