    let nextTime = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerBusyUntil[i] > time) nextTime = Math.min(nextTime, workerBusyUntil[i])
    }
    if (nextTime === Infinity) break
    time = nextTime
  }

  let makespan = 0
  for (const finish of finishTime.values()) makespan = Math.max(makespan, finish)
  return { logs, makespan }
}

