{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-bAm3M7/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { Fail } from './errors.js'
import { parseGraph } from './parse.js'
import { findCycle } from './cycle.js'
import { computeDepths, computeTiming, computePriority, packWorkers } from './schedule.js'

const WORKERS_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) {
      throw new Fail(2, 'workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new Fail(2, 'usage: cli.js waves|explain|pack <workers>')
}

function formatWaves(graph) {
  const depths = computeDepths(graph.taskNames, graph.deps)
  const timing = computeTiming(graph.taskNames, graph.deps, graph.cost)

  let maxDepth = -1
  for (const depth of depths.values()) maxDepth = Math.max(maxDepth, depth)

  const lines = []
  for (let wave = 0; wave <= maxDepth; wave++) {
    const names = graph.taskNames.filter((name) => depths.get(name) === wave)
    lines.push(`wave ${wave}: ${names.join(' ')}`)
  }

  let total = 0
  for (const t of timing.values()) total = Math.max(total, t.finish)
  lines.push(`total ${total}`)

  return lines.join('\n') + '\n'
}

function formatExplain(graph) {
  const depths = computeDepths(graph.taskNames, graph.deps)
  const timing = computeTiming(graph.taskNames, graph.deps, graph.cost)

  const lines = []
  let total = 0
  for (const name of graph.taskNames) {
    const t = timing.get(name)
    lines.push(`${name} start=${t.start} finish=${t.finish} depth=${depths.get(name)}`)
    total = Math.max(total, t.finish)
  }
  lines.push(`total ${total}`)

  return lines.join('\n') + '\n'
}

function formatPack(graph, workerCount) {
  const priority = computePriority(graph.taskNames, graph.deps, graph.cost)
  const { logs, makespan } = packWorkers(graph.taskNames, graph.deps, graph.cost, priority, workerCount)

  const lines = []
  for (let i = 0; i < workerCount; i++) {
    const entries = logs[i].map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)

  return lines.join('\n') + '\n'
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))

  const input = readFileSync(0, 'utf8')
  const graph = parseGraph(input)

  const cycle = findCycle(graph.taskNames, graph.deps)
  if (cycle) {
    throw new Fail(3, `cycle: ${cycle.join(' -> ')}`)
  }

  if (mode === 'waves') {
    process.stdout.write(formatWaves(graph))
  } else if (mode === 'explain') {
    process.stdout.write(formatExplain(graph))
  } else {
    process.stdout.write(formatPack(graph, workers))
  }
}

try {
  main()
} catch (err) {
  if (err instanceof Fail) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  }
  throw err
}
"}

