/**
 * A task's priority for `pack`: the cost of the longest chain that begins
 * at it and runs down through its dependents (the tasks that depend on
 * it) to a task that nothing depends on, its own cost plus the greatest
 * priority among its dependents (0 when nothing depends on it).
 */
export function computePriority(taskNames, deps, cost) {
  const dependents = new Map()
  for (const name of taskNames) dependents.set(name, new Set())
  for (const [dependent, depSet] of deps) {
    for (const dep of depSet) dependents.get(dep)?.add(dependent)
  }

  return computeOnDag(taskNames, dependents, (name, dependentSet, result) => {
    let best = 0
    for (const dependent of dependentSet) best = Math.max(best, result.get(dependent))
    return cost.get(name) + best
  })
}
